php -r 'require "vendor/autoload.php"; $app=require "bootstrap/app.php"; $kernel=$app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $row=Illuminate\Support\Facades\DB::table("tt_LogDebug")->select("id","Caminho","Header","Envio","created_at","momento")->where("Caminho","AdmController")->where("Header","like","%Entregadores online na ADM%")->orderByDesc("id")->first(); if(!$row){ echo "NO_ROW", PHP_EOL; exit; } echo $row->id,PHP_EOL; echo $row->Caminho,PHP_EOL; echo $row->Header,PHP_EOL; echo $row->Envio,PHP_EOL; echo $row->created_at,PHP_EOL; echo $row->momento,PHP_EOL;'